public class UserPreferenceCacheService : IUserPreferenceCache
{
    private readonly IDistributedCache _cache;
    private readonly ILogger<UserPreferenceCacheService> _logger;
    private static readonly TimeSpan CacheTTL = TimeSpan.FromMinutes(5);

    public async Task<UserPreferences?> GetAsync(string userId)
    {
        var cached = await _cache.GetStringAsync($"user-prefs:{userId}");
        if (cached is null) return null;
        return JsonSerializer.Deserialize<UserPreferences>(cached);
    }

    public async Task SetAsync(string userId, UserPreferences prefs)
    {
        var json = JsonSerializer.Serialize(prefs);
        await _cache.SetStringAsync($"user-prefs:{userId}", json,
            new DistributedCacheEntryOptions { AbsoluteExpirationRelativeToNow = CacheTTL });
    }
}
